def parsear_duracion(s):
    total_minutos = 0
    for char in s:
        if char == 'h':
            total_minutos += int(s.replace('h', '').replace('m', '')) * 60
        elif char == 'm':
            total_minutos += int(s.replace('h', '').replace('m', ''))
    return total_minutos

def es_palindromo(s):
    s = ''.join(c.lower() for c in s if c.isalnum())
    return s == s[::-1]

def aplanar(lista):
    resultado = []
    for elemento in lista:
        if isinstance(elemento, list):
            resultado.extend(aplanar(elemento))
        else:
            resultado.append(elemento)
    return resultado

def buscar(lista, x):
    izq = 0
    der = len(lista) - 1
    while izq <= der:
        medio = (izq + der) // 2
        if lista[medio] == x:
            return medio
        elif lista[medio] < x:
            izq = medio + 1
        else:
            der = medio - 1
    return -1

def agrupar_por(items, clave):
    resultado = {}
    for item in items:
        valor = item[clave]
        if valor not in resultado:
            resultado[valor] = []
        resultado[valor].append(item)
    return resultado

import re
from collections import Counter

def contar_palabras(texto):
    texto = texto.lower()
    palabras = re.findall(r'\b\w+\b', texto)
    return dict(Counter(palabras))

def rotar(lista, n):
    if not lista:
        return []
    n = n % len(lista)
    return lista[-n:] + lista[:-n] if n else lista

def a_romano(n):
    valores = [
        (1000, 'M'), (900, 'CM'), (500, 'D'), (400, 'CD'),
        (100, 'C'), (90, 'XC'), (50, 'L'), (40, 'XL'),
        (10, 'X'), (9, 'IX'), (5, 'V'), (4, 'IV'), (1, 'I')
    ]
    resultado = ''
    for valor, simbolo in valores:
        while n >= valor:
            resultado += simbolo
            n -= valor
    return resultado

def desde_romano(s):
    valores = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    prev = 0
    for char in reversed(s.upper()):
        val = valores[char]
        if val < prev:
            total -= val
        else:
            total += val
        prev = val
    return total

def mayor_racha(lista):
    if not lista:
        return None
    max_elem = lista[0]
    max_len = 1
    current_elem = lista[0]
    current_len = 1
    for elem in lista[1:]:
        if elem == current_elem:
            current_len += 1
        else:
            if current_len > max_len:
                max_len = current_len
                max_elem = current_elem
            current_elem = elem
            current_len = 1
    if current_len > max_len:
        max_len = current_len
        max_elem = current_elem
    return (max_elem, max_len)

def primos(n):
    if n < 2:
        return []
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False
    for i in range(2, int(n ** 0.5) + 1):
        if is_prime[i]:
            for j in range(i * i, n + 1, i):
                is_prime[j] = False
    return [i for i in range(2, n + 1) if is_prime[i]]

def mcd(a, b):
    while b != 0:
        a, b = b, a % b
    return a

def fusionar(intervalos):
    if not intervalos:
        return []
    sorted_intervals = sorted(intervalos, key=lambda x: x[0])
    fused = [sorted_intervals[0]]
    for inicio, fin in sorted_intervals[1:]:
        if fin >= fused[-1][0] and inicio <= fused[-1][1]:
            fused[-1] = (fused[-1][0], max(fused[-1][1], fin))
        else:
            fused.append((inicio, fin))
    return fused

def comprimir(s):
    if not s:
        return s
    resultado = []
    contador = 1
    for i in range(1, len(s)):
        if s[i] == s[i-1]:
            contador += 1
        else:
            resultado.append(s[i-1] + str(contador))
            contador = 1
    resultado.append(s[-1] + str(contador))
    comprimido = ''.join(resultado)
    return comprimido if len(comprimido) < len(s) else s

def balanceado(s):
    stack = []
    for char in s:
        if char in '({[':
            stack.append(char)
        elif char in ')}]':
            if not stack:
                return False
            top = stack.pop()
            if (char == ')' and top != '(') or \
               (char == '}' and top != '{') or \
               (char == ']' and top != '['):
                return False
    return len(stack) == 0

def transpuesta(m):
    if not m:
        return []
    return [[m[i][j] for i in range(len(m))] for j in range(len(m[0]))]

def raiz_digital(n):
    while n >= 10:
        n = sum(int(d) for d in str(n))
    return n

def n_esimo_mayor(lista, n):
    if n < 1:
        return None
    distintos = list(set(lista))
    if len(distintos) < n:
        return None
    return sorted(distintos, reverse=True)[n - 1]

def formatear_bytes(n):
    if n < 1024:
        return f"{n} B"
    elif n < 1048576:
        return f"{n / 1024:.1f} KB"
    elif n < 1073741824:
        return f"{n / 1048576:.1f} MB"
    else:
        return f"{n / 1073741824:.1f} GB"
